def validate() -> None:
    assert set(ROWS) == {"pot_odds","equity","mdf","spr","combo","vocabulary","icm","bet_sizing","range","hand_reasoning"}
    seen: set[str] = set()
    for category, raw in ROWS.items():
        rows = [row.strip() for row in raw.strip().splitlines() if row.strip()]
        assert len(rows) == 7, (category, len(rows))
        for row in rows:
            parts = row.split("|")
            assert len(parts) == 9, (category, row)
            slug, prompt, *rest = parts
            correct, wrong1, wrong2, wrong3, explanation, source, level = rest
            assert slug not in seen, slug
            seen.add(slug)
            assert prompt and explanation and len(explanation) >= 15
            assert len({correct,wrong1,wrong2,wrong3}) == 4, slug
            assert source in SOURCES, (slug, source)
            assert level in {"standard","intermediate"}, (slug, level)
            if all(x.endswith("%") for x in (correct,wrong1,wrong2,wrong3)):
                num = [float(x[:-1]) for x in (correct,wrong1,wrong2,wrong3)]
                assert all(abs(x-num[0]) >= 10 for x in num[1:]), (slug, num)

validate()
